PREFIX genex: <http://purl.org/genex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?expressionEntity ?value ?type
WHERE {
  {
    # 子查询 A: 找最高值 (Highest)
    SELECT ?expressionEntity ?val ("Highest" AS ?type) WHERE {
       ?expressionEntity genex:hasExpressionLevel ?levelStr .
       # 关键优化：强制转为浮点数，确保 10.0 > 2.0
       BIND(xsd:double(?levelStr) AS ?val)
    } 
    ORDER BY DESC(?val) 
    LIMIT 1
  }
  UNION
  {
    # 子查询 B: 找最低值 (Lowest)
    SELECT ?expressionEntity ?val ("Lowest" AS ?type) WHERE {
       ?expressionEntity genex:hasExpressionLevel ?levelStr .
       BIND(xsd:double(?levelStr) AS ?val)
    } 
    ORDER BY ASC(?val) 
    LIMIT 1
  }
  # 统一输出变量名
  BIND(?val AS ?value)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs:   <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?entity ?label ?description
WHERE {
  ?entity dcterms:description ?description .

  FILTER(REGEX(LCASE(STR(?description)), "part of( the)? cerebellum"))

  FILTER(STRSTARTS(STR(?entity), "http://purl.obolibrary.org/obo/UBERON_"))

  OPTIONAL { ?entity rdfs:label ?label }
}
ORDER BY LCASE(COALESCE(STR(?label), STR(?entity)))

PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT ?cell ?description
WHERE {
  ?cell dcterms:description ?description .

  FILTER(REGEX(STR(?description), "pedigree ABarp[ap]+"))
}

PREFIX genex: <http://purl.org/genex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?event ?level
WHERE {
  {
    SELECT (AVG(xsd:double(?valStr)) AS ?averageLevel)
    WHERE {
      ?x genex:hasExpressionLevel ?valStr .
    }
  }
  ?event genex:hasExpressionLevel ?levelStr .

  # 类型转换：把当前事件的字符串值转为数字
  BIND(xsd:double(?levelStr) AS ?level)
  FILTER (?level > ?averageLevel)
}

